def build_body(pairs: list[tuple[str, str]]) -> str:
    return "\x1e".join(f"<b>{ar}</b>\n{fa}" for ar, fa in pairs)


ITEMS = [
    ("dua-ale-yasin", "دعای آل یاسین", ALE_YASIN_PAIRS),
    ("dua-ahd", "دعای عهد", AHD_PAIRS),
    ("dua-moshkel-gosha", "دعای مشکل‌گشا", MOSHKEL_PAIRS),
]


async def main() -> None:
    async with session_scope() as session:
        for slug, title, pairs in ITEMS:
            asset = await content_service.register_devotional_text(
                session, content_type="DUA", slug=slug, title=title, text_body=build_body(pairs),
            )
            print(f"registered {slug!r}: {len(asset.text_body)} chars, {len(pairs)} chunks")


if __name__ == "__main__":
    asyncio.run(main())
